            key1 = str(i)
            if key1 in nearest_neighbors:
                li = nearest_neighbors[key1]
            elif i in nearest_neighbors:
                li = nearest_neighbors[i]
            if isinstance(li, list) and li:
                # Only consider top-k neighbors
                for j in li[:k]:
                    if j in route_of and j != i:
                        # Savings computed for merge potential only for endpoints later; keep now.
                        pair_savings.append((i, j))
                continue
        # Fallback: limited all-pairs for determinism
        # (O(n^2) can be large; use distance-based ordering to cut)
        for j_idx in range(i_idx + 1, len(customers_sorted)):
            j = customers_sorted[j_idx]
            # Simple cutoff: if depot distances are too large compared to current, still allow; keep all
            pair_savings.append((i, j))

    # Compute savings and sort deterministically.
    # saving(i->j) = d(depot,i)+d(depot,j)-d(i,j); try both directions by considering ordered pairs later.
    # We'll create ordered candidate merges from unordered pairs.
    candidates = []
    seen = set()
    for a, b in pair_savings:
        if a == b:
            continue
        if a > b:
            a, b = b, a
        if (a, b) in seen:
            continue
        seen.add((a, b))
        s = matrix[depot][a] + matrix[depot][b] - matrix[a][b]
        # Deterministic tie-break: prefer higher saving, then smaller endpoints
        candidates.append((s, a, b))

    candidates.sort(key=lambda x: (-x[0], x[1], x[2]))

    # Merge logic with endpoints
    # routes[r] can be reversed, and route_of points to route index; update on merge.
    # We will maintain routes in-place but with deterministic rebuild on merges.
    active = [True] * len(routes)
    def endpoints_of_route(ridx):
        r = routes[ridx]
        if not r:
            return None, None
        return r[0], r[-1]

    # To avoid heavy data structure updates, do controlled merges:
    # When merge occurs, we mark one route inactive and set it to None; later we compact.
    for _, a, b in candidates:
        ra = route_of.get(a, None)
        rb = route_of.get(b, None)
        if ra is None or rb is None or ra == rb:
            continue
        if ra < 0 or rb < 0 or ra >= len(routes) or rb >= len(routes):
            continue
        if not active[ra] or not active[rb]:
            continue

        # Check whether a and b are feasible endpoints for merging either orientation.
        a_start, a_end = endpoints_of_route(ra)
        b_start, b_end = endpoints_of_route(rb)
        # Four merge cases:
        # If a is end of route ra and b is start of route rb: ra + rb
        # If b is end of route rb and a is start of route ra: rb + ra
        # Else if a is start and b is start: reverse ra then merge ra_rev + rb
        # Else if a is end and b is end: ra + rb_rev
        merged = False
        # Case 1: a_end == a and b_start == b
        if a_end == a and b_start == b:
            if route_load(routes[ra]) + route_load(routes[rb]) <= capacity:
                routes[ra] = routes[ra] + routes[rb]
                active[rb] = False
                for x in routes[rb]:
                    route_of[x] = ra
                merged = True
        # Case 2: b_end == b and a_start == a
        if (not merged) and b_end == b and a_start == a:
            if route_load(routes[ra]) + route_load(routes[rb]) <= capacity:
                routes[rb] = routes[rb] + routes[ra]
                active[ra] = False
                newr = rb
                for x in routes[ra]:
                    route_of[x] = newr
                merged = True
        # Case 3: a_start == a and b_start == b => reverse ra
        if (not merged) and a_start == a and b_start == b:
            if route_load(routes[ra]) + route_load(routes[rb]) <= capacity:
                routes[ra] = list(reversed(routes[ra])) + routes[rb]
                active[rb] = False
                for x in routes[rb]:
                    route_of[x] = ra
                merged = True
        # Case 4: a_end == a and b_end == b => reverse rb
        if (not merged) and a_end == a and b_end == b:
            if route_load(routes[ra]) + route_load(routes[rb]) <= capacity:
                routes[ra] = routes[ra] + list(reversed(routes[rb]))
                active[rb] = False
                for x in routes[rb]:
                    route_of[x] = ra
                merged = True

        if merged:
            # keep route costs stable; nothing else
            pass

    # Compact active routes and ensure each active route is stored
    compact_routes = []
    remap = {}
    for idx in range(len(routes)):
        if active[idx] and routes[idx]:
            remap[idx] = len(compact_routes)
            compact_routes.append(routes[idx])
    routes = compact_routes

    # If savings failed to produce full coverage (shouldn't), fallback to greedy insertion
    # Ensure every customer is present.
    present = set()
    for r in routes:
        for x in r:
            present.add(x)
    missing = [c for c in customers if c not in present]
    if missing:
        # Simple greedy: place each missing customer into best feasible route, else new route
        for m in missing:
            best_r = None
            best_pos_cost = None
            for ri, r in enumerate(routes):
                if route_load(r) + demands[m] > capacity:
                    continue
                # best insertion position in r
                best_local = None
                if not r:
                    local_delta = matrix[depot][m] + matrix[m][depot]
                    best_local = (local_delta, 0)
                else:
                    # try insert between i and i+1 (including ends)
                    for pos in range(len(r) + 1):
                        # route with m inserted at pos
                        if pos == 0:
                            c = matrix[depot][m] + matrix[m][r[0]]
                        elif pos == len(r):
                            c = matrix[r[-1]][m] + matrix[m][depot]
                        else:
                            c = matrix[r[pos - 1]][m] + matrix[m][r[pos]]
                            c -= matrix[r[pos - 1]][r[pos]]
                        if best_local is None or c < best_local[0] or (c == best_local[0] and (ri, pos) < (best_r, best_pos_cost[1] if best_pos_cost else 0)):
                            best_local = (c, pos)
                if best_local is not None:
                    if best_pos_cost is None or best_local[0] < best_pos_cost[0]:
                        best_pos_cost = best_local
                        best_r = ri
            if best_r is None:
                routes.append([m])
            else:
                pos = best_pos_cost[1]
                routes[best_r] = routes[best_r][:pos] + [m] + routes[best_r][pos:]

    # --- Local search: deterministic 2-opt within routes and relocate between routes ---
    # Keep it small but targeted: one pass 2-opt then a few relocate improvements.
    def two_opt_route(r):
        n = len(r)
        if n < 4:
            return r
        improved = True
        # Only first improvement to remain deterministic and fast
        while improved:
            improved = False
            for i in range(n - 3):
                a = r[i]
                b = r[i + 1]
                for k in range(i + 2, n - 1):
                    c = r[k]
                    d = r[k + 1]
                    # If replacing edges (a-b) and (c-d) with (a-c) and (b-d) improves
                    cur = matrix[a][b] + matrix[c][d]
                    new = matrix[a][c] + matrix[b][d]
                    if new < cur:
                        r = r[:i + 1] + list(reversed(r[i + 1:k + 1])) + r[k + 1:]
                        improved = True
                        n = len(r)
                        break
                if improved:
                    break
        return r

    routes_changed = True
    # Intra-route 2-opt
    if routes_changed:
        for i in range(len(routes)):
            routes[i] = two_opt_route(routes[i])

